import type { Pregunta } from '../quiz';

// Nivel MEDIA (español) · 142 preguntas: distinguir conceptos y reconocerlos en situaciones concretas.
// Convención: la PRIMERA opción es siempre la correcta (en pantalla se mezclan al azar).

export const media: Pregunta[] = [
  // ── El modelo ecológico ──
  { p: 'Diego creció viendo a su padre gritarle a su madre. Según el modelo ecológico, ¿qué es ese antecedente?', o: ['Un factor de riesgo individual: hace más probable la violencia, pero no la justifica', 'La causa principal de su violencia, aunque no lo exime de responsabilidad', 'Un factor relacional, porque ocurrió dentro de su familia de origen', 'Un factor que deja de pesar si en su barrio no hay violencia'], e: 'La historia personal es nivel individual (OMS, 2002). No es “la causa”: muchas personas que crecieron con violencia nunca la ejercen. El nivel relacional son los vínculos actuales: pareja, familia, amigos.', t: 'modelo-ecologico' },
  { p: 'Hacinamiento, desempleo y falta de espacios para el deporte en un barrio, ¿cómo se relacionan con la violencia según el modelo?', o: ['Son factores comunitarios que aumentan el riesgo, pero no la explican solos', 'Son la causa de fondo de la violencia de género en los barrios populares', 'Son factores sociales, porque dependen de la economía de todo el país', 'No influyen, porque la violencia de género atraviesa todas las clases'], e: 'Son factores del nivel comunitario: suben el riesgo, pero no alcanzan para explicar la violencia. Que la violencia atraviese todas las clases sociales no quiere decir que el contexto no influya.', t: 'modelo-ecologico' },
  { p: 'Que en una pareja uno maneje todo el dinero y tome todas las decisiones, ¿qué es desde el modelo ecológico?', o: ['Un factor de riesgo del nivel relacional', 'Un factor de riesgo del nivel comunitario', 'Una forma de violencia simbólica', 'Un rasgo de personalidad del nivel individual'], e: 'Es un factor de los vínculos cercanos: nivel relacional (Heise, 1998). Según cómo se ejerza, además puede ser violencia económica, no simbólica.', t: 'modelo-ecologico' },
  { p: '¿Por qué el modelo ecológico propone intervenir en varios niveles a la vez?', o: ['Porque la violencia se sostiene en capas distintas que se refuerzan entre sí', 'Porque todavía no se sabe en qué nivel empieza la violencia', 'Porque intervenir sobre quien agrede no tiene ningún efecto', 'Porque el Estado no puede intervenir dentro de una casa'], e: 'La violencia se sostiene en muchas capas a la vez, y por eso también se puede frenar desde muchos lugares. Intervenir con quien agrede es una de esas puertas, y el Estado sí debe intervenir en lo que pasa dentro de una casa.', t: 'modelo-ecologico' },
  { p: 'Frente a un caso de acoso escolar, ¿qué agrega el enfoque ecológico?', o: ['Mirar todos los niveles y el sentido que le dan quienes participan', 'Identificar a quien acosa para aplicarle la sanción adecuada', 'Buscar en la historia familiar de quien acosa la causa', 'Medir cuántas veces ocurrió para saber si es grave'], e: 'El enfoque invita a salir de la búsqueda del “chico problemático” y mirar todos los niveles, incluido el sentido que los propios actores le dan al acoso.', t: 'modelo-ecologico' },
  { p: 'Cuando se habla de un “modelo” en políticas públicas contra la violencia, ¿a qué se refiere?', o: ['A cómo una ley entiende el problema y organiza los recursos', 'A un programa que funcionó en otro país y se aplica sin cambios', 'A la lista de tipos y modalidades de violencia que reconoce la ley', 'A un protocolo para que la policía tome las denuncias'], e: 'En políticas públicas, el modelo es el conjunto de ideas y componentes que definen el problema y organizan acciones y recursos (de autoridad, económicos, humanos y materiales).', t: 'modelo-ecologico' },

  // ── Violencia de género ──
  { p: 'En una comisaría se niegan a tomarle la denuncia a una mujer y le dicen que “arregle las cosas en su casa”. ¿Qué modalidad es?', o: ['Institucional', 'Doméstica', 'Psicológica', 'Pública-política'], e: 'Un agente del Estado obstaculiza el acceso a un derecho: modalidad institucional. Psicológica es un tipo, no una modalidad, y doméstica sería si viniera de su grupo familiar.', t: 'violencia-de-genero' },
  { p: 'En una entrevista de trabajo le preguntan a una mujer si piensa tener hijos y le piden un test de embarazo. ¿Qué modalidad es?', o: ['Laboral', 'Contra la libertad reproductiva', 'Institucional', 'Obstétrica'], e: 'Es laboral: discrimina en el acceso al empleo. No es contra la libertad reproductiva, porque no le impide decidir sus embarazos, aunque use la maternidad para discriminarla.', t: 'violencia-de-genero' },
  { p: 'Un programa de televisión se burla de una mujer que denunció a su pareja. ¿Qué modalidad de violencia es?', o: ['Mediática', 'Simbólica', 'En el espacio público', 'Institucional'], e: 'Difundir en medios mensajes que humillan es la modalidad mediática. Simbólica es un tipo de violencia (art. 5), no una modalidad.', t: 'violencia-de-genero' },
  { p: 'En el parto, el equipo de salud no le explica nada a la mujer, la reta y le hace intervenciones innecesarias. ¿Qué modalidad es?', o: ['Obstétrica', 'Contra la libertad reproductiva', 'Institucional', 'Física'], e: 'El trato deshumanizado y el abuso de medicalización en la atención del parto es violencia obstétrica (Ley 25.929). Física es un tipo, no una modalidad.', t: 'violencia-de-genero' },
  { p: 'Un grupo amenaza en la calle a una candidata para que baje su candidatura porque “la política no es para mujeres”. ¿Qué modalidad es?', o: ['Pública-política', 'En el espacio público', 'Mediática', 'Institucional'], e: 'Busca impedir su participación política: modalidad pública-política. La modalidad en el espacio público se refiere a conductas con connotación sexual.', t: 'violencia-de-genero' },
  { p: '¿Cuál de estas afirmaciones sobre la definición de la Ley 26.485 es correcta?', o: ['Incluye la violencia que ejercen agentes del Estado', 'Se aplica a parejas actuales, pero no a exparejas', 'Incluye lo digital desde su sanción, en 2009', 'Considera violencia las acciones, pero no las omisiones'], e: 'El art. 4 incluye la violencia ejercida desde el Estado. También abarca a exparejas y las omisiones, y lo digital se sumó en 2023 con la Ley 27.736.', t: 'violencia-de-genero' },
  { p: 'En el iceberg, ¿dónde están “humillar, desvalorizar e ignorar”?', o: ['Bajo la superficie: son explícitas, pero no se ven', 'En la punta: son las formas más visibles', 'En la base: son las formas más sutiles', 'En la línea del agua: se ven solo a medias'], e: 'Están bajo la superficie: son explícitas, pero quedan ocultas a los demás. En la base están las formas sutiles, como el humor y el lenguaje sexistas o el control.', t: 'violencia-de-genero' },

  // ── Ciclo de la violencia ──
  { p: 'Después de semanas de roces, él le rompe el celular y la amenaza, pero no la golpea. ¿En qué fase están?', o: ['Período violento', 'Acumulación de tensión', 'Temor a perder la relación', 'Todavía no hay violencia, solo tensión'], e: 'Romper sus cosas y amenazarla ya es violencia (psicológica y económica): es el período violento, aunque no haya golpes.', t: 'ciclo-de-la-violencia' },
  { p: 'Ante la pregunta “¿por qué no se va?”, ¿qué señala el tema?', o: ['Que pone el peso en la víctima y no en quien ejerce violencia', 'Que es la pregunta que más la ayuda a tomar conciencia', 'Que sugiere una salida que la ley no permite sin denuncia', 'Que tiene sentido sobre todo cuando no hay hijos'], e: 'La pregunta pone la responsabilidad en ella. Salir es difícil por el miedo, el aislamiento, la dependencia económica, los hijos y la esperanza, y no hace falta denunciar para irse ni para pedir ayuda.', t: 'ciclo-de-la-violencia' },
  { p: 'Él no la golpea, pero decide con quién se ve, maneja su dinero y le revisa el celular todos los días. ¿Qué describe mejor la situación?', o: ['Control coercitivo: es violencia aunque no haya golpes', 'La fase de acumulación de tensión, antes de la violencia', 'Celos intensos, propios de una pareja muy unida', 'Un conflicto de pareja que se resuelve negociando'], e: 'Evan Stark llamó control coercitivo al control constante de la vida de la otra persona. Es violencia psicológica y económica, aunque no haya estallidos ni golpes.', t: 'ciclo-de-la-violencia' },
  { p: '¿Por qué el momento de la separación requiere especial cuidado?', o: ['Porque suele ser un momento de mayor riesgo para ella', 'Porque la ley exige una denuncia antes de separarse', 'Porque es cuando empieza la fase de luna de miel', 'Porque los hijos quedan a cargo de quien se va'], e: 'El momento de la separación suele ser de mayor riesgo. Por eso conviene pensar un plan de seguridad y pedir orientación a la Línea 144.', t: 'ciclo-de-la-violencia' },
  { p: 'Una amiga te cuenta que su pareja la amenaza, pero no quiere dejarlo. ¿Qué es lo más adecuado?', o: ['Creerle, respetar sus tiempos y contarle de la Línea 144', 'Hablar con él para que entienda el daño que hace', 'Darle un plazo para que lo deje y, si no, alejarte', 'Decirle que, si se queda, ya no podés ayudarla'], e: 'Creerle, no juzgarla y respetar sus tiempos la mantiene cerca de ayuda. Confrontar a quien ejerce violencia puede aumentar el riesgo para ella.', t: 'ciclo-de-la-violencia' },

  // ── Efectos de la violencia de género en las infancias ──
  { p: 'Una niña de 8 años cuida a sus hermanos y consuela a su madre después de cada episodio violento. ¿Qué señal muestra?', o: ['Parentalización', 'Normalización', 'Conducta regresiva', 'Aislamiento social'], e: 'Asume roles de cuidado y protección que no corresponden a su edad.', t: 'efectos-en-las-infancias' },
  { p: 'Un niño vive violencia en su casa, pero no muestra ninguna señal visible. ¿Qué se puede concluir?', o: ['Que igual puede estar afectado: muchos no muestran nada', 'Que probablemente tiene buenos recursos para afrontarla', 'Que conviene esperar a que aparezcan señales para intervenir', 'Que no lo alcanzó, porque no era dirigida a él'], e: 'Que no aparezcan señales no descarta el daño: muchas niñas y niños no lo expresan de ningún modo. Esperar señales o pensar que no lo alcanzó deja sin ayuda a una víctima indirecta.', t: 'efectos-en-las-infancias' },
  { p: 'Un adolescente dice que en su casa "se grita y se pega como en todas las casas". ¿Qué señal muestra?', o: ['Normalización', 'Parentalización', 'Conducta regresiva', 'Estrés postraumático'], e: 'Ver la violencia como una forma "normal" de relacionarse, o quitarle importancia, es normalizarla.', t: 'efectos-en-las-infancias' },
  { p: 'Al acompañar a una mujer en situación de violencia, ¿qué recomienda la guía sobre sus hijos?', o: ['Incluirlos, con espacios propios, y que la madre participe', 'Priorizar a la madre y sumarlos cuando ella esté mejor', 'Trabajar con ellos por separado, sin la madre', 'Esperar a que ellos pidan ayuda, para respetar sus tiempos'], e: 'Hay que incluir también a hijas e hijos, con espacios específicos, y que la madre participe del acompañamiento. Postergarlos o esperar a que pidan ayuda los deja solos.', t: 'efectos-en-las-infancias' },
  { p: '¿Qué es la victimización secundaria?', o: ['El daño que vuelve a causar una intervención inadecuada', 'La violencia que sufre un hermano que no era el blanco', 'Una segunda agresión del mismo agresor, más grave', 'El daño de los chicos que son víctimas indirectas'], e: 'Son las intervenciones fragmentadas o inadecuadas (de instituciones o profesionales) que vuelven a dañar a quien ya fue víctima. No es lo mismo que ser víctima indirecta.', t: 'efectos-en-las-infancias' },
  { p: 'Sobre el contacto con el padre denunciado, ¿qué postura predomina en las sentencias?', o: ['Decidir según la gravedad, guiándose por el interés superior del niño', 'Suspenderlo de forma automática apenas hay una denuncia', 'Mantenerlo, porque el vínculo con el padre es un derecho del niño', 'Dejar que lo decidan los hijos, según su edad'], e: 'Predomina decidir caso por caso según la gravedad, guiándose por el interés superior del niño. Otra postura, de profesionales y juristas, pide suspenderlo mientras se investiga; escuchar a los hijos importa, pero no deciden solos.', t: 'efectos-en-las-infancias' },

  // ── Igualdad y no discriminación ──
  { p: '¿Qué implica para los Estados el principio de igualdad y no discriminación?', o: ['Una obligación reforzada con los grupos en situación de vulnerabilidad', 'Tratar a todas las personas de forma idéntica, sin distinciones', 'Una meta a la que los Estados deben llegar de forma gradual', 'Un deber que recae sobre todo en los jueces'], e: 'Implica una obligación reforzada con los grupos vulnerables (Compendio de la CIDH, cap. 4). Tratar igual a quienes están en desigualdad puede mantener la discriminación.', t: 'igualdad-y-no-discriminacion' },
  { p: '¿Qué deben garantizar especialmente los Estados a las mujeres en situación de pobreza?', o: ['Salud, trabajo y derechos económicos', 'El voto y la participación política', 'Acceso a la justicia y a la información', 'Educación sexual y derechos digitales'], e: 'Atención especial a sus derechos económicos y al ejercicio efectivo de la salud y el trabajo. Los otros derechos también importan, pero no son el foco que marca la CIDH para la pobreza.', t: 'igualdad-y-no-discriminacion' },
  { p: 'Según la CEDAW, la discriminación contra la mujer es toda distinción basada en el sexo que…', o: ['Menoscabe o anule sus derechos, aunque no haya intención', 'Se haga con la intención expresa de discriminar a una mujer', 'Esté escrita en una ley, un decreto u otra norma oficial', 'Ocurra en el ámbito público, y no en el ámbito privado'], e: 'Por objeto o por resultado, en cualquier esfera: no hace falta intención, ni que esté escrita, y abarca también lo privado.', t: 'igualdad-y-no-discriminacion' },
  { p: '¿Qué tipo de política exige la CEDAW a los Estados para eliminar la discriminación?', o: ['Inmediata, comprehensiva y multisectorial', 'Progresiva, comprehensiva y multisectorial', 'Inmediata, parcial y multisectorial', 'Inmediata, comprehensiva y por sectores'], e: 'La CEDAW exige una política inmediata (no gradual), comprehensiva (no parcial) y multisectorial (no organizada sector por sector).', t: 'igualdad-y-no-discriminacion' },
  { p: '¿En qué instrumentos se apoyan los estándares interamericanos sobre las mujeres?', o: ['DADDH, CADH y Belém do Pará', 'CEDAW, OMS y Ley 26.485', 'Leyes 26.618, 26.743 y 26.791', 'Declaración de Bogotá y OPS'], e: 'Declaración Americana, Convención Americana y Convención de Belém do Pará.', t: 'igualdad-y-no-discriminacion' },

  // ── Legislación ──
  { p: '¿Qué ley argentina aprobó la Convención de Belém do Pará?', o: ['La Ley 24.632', 'La Ley 26.485', 'La Ley 26.061', 'La Ley 27.736'], e: 'La Ley 24.632 (1996) aprobó la Convención de Belém do Pará.', t: 'legislacion' },
  { p: '¿Qué incorporó la Ley 27.736 (2023) a la Ley 26.485?', o: ['El espacio digital y la violencia digital', 'La violencia obstétrica en la atención del parto', 'La violencia política como un tipo nuevo', 'La modalidad de violencia en el espacio público'], e: 'La Ley Olimpia sumó lo digital. La violencia política llegó con la Ley 27.533 y el espacio público con la 27.501 (2019); la obstétrica estaba desde 2009.', t: 'legislacion' },
  { p: 'El art. 3 de la Ley 26.485 protege el derecho a un trato respetuoso que evite…', o: ['La revictimización', 'La publicidad', 'La reconciliación', 'La investigación'], e: 'Evitar toda conducta, acto u omisión que produzca revictimización.', t: 'legislacion' },
  { p: 'Según el art. 7 de la Ley 26.485, ¿cómo debe ser la asistencia a las mujeres que padecen violencia?', o: ['Gratuita, rápida, transparente y eficaz', 'Gratuita y rápida, una vez hecha la denuncia', 'Rápida y eficaz, a cargo de cada provincia', 'Gratuita, a través de organizaciones sociales'], e: 'Integral, oportuna, gratuita, rápida, transparente y eficaz. No depende de una denuncia ni se delega en ONG.', t: 'legislacion' },
  { p: '¿Qué prohíbe el art. 7 de la Ley 26.485 sobre la información de situaciones de violencia?', o: ['Difundirla sin autorización de quien la padece', 'Guardarla en registros oficiales del Estado nacional', 'Usarla para estadísticas anónimas', 'Compartirla con la justicia cuando lo pide'], e: 'Protege la confidencialidad y la intimidad de quien padece la violencia.', t: 'legislacion' },
  { p: 'Según el art. 9 de la Ley 26.485, ¿qué modelos de abordaje NO se admiten?', o: ['Los que incluyan mediación o negociación', 'Los que trabajen también con el varón que agredió', 'Los que dependan de organismos provinciales', 'Los que funcionen sin denuncia previa'], e: 'No se admite la mediación ni la negociación. El trabajo con los varones que ejercen violencia sí está previsto, y la asistencia no requiere denuncia.', t: 'legislacion' },
  { p: '¿Qué contempla el inciso 11 del art. 80 del Código Penal?', o: ['Matar a una mujer mediando violencia de género', 'Matar por odio de género o a la orientación sexual', 'Matar a la pareja o expareja, conviva o no', 'Matar para hacer sufrir a una expareja'], e: 'El inciso 11 es el femicidio: matar a una mujer cuando lo hace un hombre y media violencia de género, con prisión perpetua. Las otras opciones son los incisos 4, 1 y 12.', t: 'legislacion' },

  // ── Micromachismos ──
  { p: 'Usar el silencio para no dar explicaciones e imponer el no diálogo es un micromachismo…', o: ['Encubierto', 'Utilitario', 'De crisis', 'Coercitivo'], e: 'Es una forma de “creación de falta de intimidad”, dentro de los encubiertos.', t: 'micromachismos' },
  { p: 'Cuando la mujer gana poder, aparecen maniobras para volver a la desigualdad anterior. ¿Qué categoría es?', o: ['De crisis', 'Utilitarios', 'Encubiertos', 'Coercitivos'], e: 'Los de crisis fuerzan la permanencia en el statu quo desigual cuando se desequilibra.', t: 'micromachismos' },
  { p: 'Retener poder mediante la fuerza psicológica o moral es un micromachismo…', o: ['Coercitivo', 'Encubierto', 'Utilitario', 'De crisis'], e: 'Los coercitivos usan la fuerza psicológica o moral masculina.', t: 'micromachismos' },
  { p: 'Responderle a una mujer “exagerás” o “estás loca” cuando reclama es…', o: ['Inocentización culpabilizadora', 'Seudonegociación', 'Creación de falta de intimidad', 'Autoindulgencia'], e: 'El varón se ubica como juez y nunca como responsable.', t: 'micromachismos' },
  { p: '¿Qué es el poder autoafirmativo?', o: ['La capacidad de existir y decidir con autonomía', 'El poder de cuidar y sostener a otras personas', 'El control sobre las decisiones de otras personas', 'La autoridad que da tener mayores ingresos'], e: 'Es el poder de existir y decidir por uno mismo. El de cuidar y sostener es el heteroafirmativo, el que tradicionalmente se les reconoció a las mujeres; controlar a otros es dominio.', t: 'micromachismos' },
  { p: 'Según Bonino, cuando un varón no reconoce los aportes de su pareja (“ninguneo”), en ella aparece…', o: ['Hambre de afecto: valora de más lo poco que recibe', 'Indiferencia: deja de esperar reconocimiento', 'Más independencia: busca reconocimiento afuera', 'Enojo abierto: le reclama cada vez más'], e: 'Bonino describe el hambre de afecto: ella termina valorando de más lo poco que él da.', t: 'micromachismos' },

  // ── Mitos del amor romántico y celos ──
  { p: '“Si me cela, es porque me quiere”. ¿Qué confusión hay detrás de esta idea?', o: ['Confundir el amor con la posesión', 'Confundir el amor con la pasión', 'Confundir el enamoramiento con el amor', 'Confundir el cuidado con la protección'], e: 'Los celos expresan deseo de posesión, no amor. Por eso es uno de los mitos más peligrosos: hace pasar el control por cariño.', t: 'mitos-del-amor-romantico' },
  { p: 'Una mujer sigue en una relación violenta convencida de que su amor va a cambiar a su pareja. ¿Qué mito aparece?', o: ['El amor todo lo puede', 'La media naranja', 'Los celos son amor', 'El amor a primera vista'], e: 'Sostiene la esperanza de que el amor va a cambiar a la pareja y hace más difícil salir o pedir ayuda (Herrezuelo Sáez, 2013).', t: 'mitos-del-amor-romantico' },
  { p: 'Una persona controla; la otra se retrae; la primera lo toma como prueba y controla más. ¿Qué describe?', o: ['El círculo de los celos', 'La socialización diferencial', 'La cosificación', 'El balance entre seguridad y libertad'], e: 'Es el círculo de los celos: el retraimiento se lee como prueba de la sospecha y el control aumenta.', t: 'mitos-del-amor-romantico' },
  { p: 'Una pareja “acuerda” que ninguno puede tener amistades propias. Según la guía…', o: ['Es control, aunque se lo llame acuerdo', 'Es válido, porque lo decidieron los dos', 'Es una regla propia de la pareja, como plantea Perel', 'Es sano si lo revisan cada tanto'], e: 'Prohibir las amistades aísla y es control, aunque se lo llame acuerdo. Perel habla de que cada pareja arma sus reglas, pero no de reglas que aíslan.', t: 'mitos-del-amor-romantico' },
  { p: 'Ver a una mujer como un objeto que le pertenece al varón se llama…', o: ['Cosificación', 'Socialización diferencial', 'Androcentrismo', 'Personalización'], e: 'La cosificación impide verla como una persona con voluntad y derechos (Batres, 1989).', t: 'mitos-del-amor-romantico' },
  { p: 'Según Mitchell, ¿qué deseamos en una pareja?', o: ['Seguridad y, a la vez, novedad y autonomía', 'Seguridad, aunque se pierda autonomía', 'Novedad, aunque se pierda estabilidad', 'Que el otro adivine lo que necesitamos'], e: 'Mitchell (2002) plantea que queremos las dos cosas a la vez: lo previsible del hogar y también autonomía y novedad. El desafío es equilibrarlas, no elegir una.', t: 'mitos-del-amor-romantico' },

  // ── Patriarcado y masculinidades ──
  { p: 'Según Klaudio Duarte, ¿cómo se reproduce el patriarcado?', o: ['Con sexismo, homofobia y heteronormatividad', 'Con alcoholismo, adicción al trabajo y violencia', 'Con la competencia y los logros externos', 'Con las leyes y las instituciones del Estado'], e: 'Duarte lo explica por el sexismo, la homofobia y la heteronormatividad. Alcohol, trabajo y violencia son las manifestaciones dañinas que describe Holloway.', t: 'patriarcado-y-masculinidades' },
  { p: 'Según Kali Holloway, ¿cuáles son las manifestaciones más dañinas de la masculinidad tradicional?', o: ['Alcohol, adicción al trabajo y violencia', 'Aislamiento, silencio y falta de amigos', 'Competencia, ambición y éxito laboral', 'Enojo, celos y control de la pareja'], e: 'Holloway nombra el alcoholismo, la adicción al trabajo y la violencia. Las otras opciones describen rasgos del mandato, pero no son las que ella señala.', t: 'patriarcado-y-masculinidades' },
  { p: '¿Qué es la “muerte espiritual” que menciona Holloway?', o: ['Trauma, desconexión y depresión', 'La pérdida del sentido de la vida por el trabajo', 'El aislamiento de amigos y familia', 'La renuncia a la fe religiosa'], e: 'Holloway llama así al trauma, la desconexión y la depresión que producen los mandatos, aunque no lleguen a matar.', t: 'patriarcado-y-masculinidades' },
  { p: 'Según Marvin Allen, ¿qué le pasa a quien viola el código masculino?', o: ['Es humillado', 'Es protegido por el grupo', 'Es imitado por otros varones', 'Es tolerado si tiene éxito'], e: 'Allen describe la humillación como castigo para quien no cumple el código: por eso cuesta tanto salirse del mandato.', t: 'patriarcado-y-masculinidades' },
  { p: 'Según Terry Real, ¿cómo suelen procesar el dolor muchos varones?', o: ['Lo vuelcan hacia afuera, contra sí o contra otros', 'Lo vuelcan hacia adentro y se culpan por lo que pasa', 'Lo hablan con amigos de confianza cuando lo necesitan', 'Lo elaboran a través del trabajo y del deporte'], e: 'Muchos varones lo exteriorizan, como “víctimas coléricas”; volcarlo hacia adentro y culparse es lo que Real observa más en mujeres.', t: 'patriarcado-y-masculinidades' },
  { p: '¿Por qué la depresión de muchos varones no se diagnostica?', o: ['Porque la tapan el enojo, el consumo o el exceso de trabajo', 'Porque los varones se deprimen mucho menos', 'Porque sus síntomas son iguales a los de las mujeres', 'Porque interiorizan el dolor y se culpan'], e: 'El dolor exteriorizado (enojo constante, alcohol, trabajar sin parar) esconde la depresión. Interiorizar y culparse es el patrón que Real ve más en mujeres.', t: 'patriarcado-y-masculinidades' },

  // ── Violencia en el fútbol ──
  { p: 'Un hincha que jamás pelearía en la calle insulta y tira objetos en la cancha. ¿Qué muestra, según la guía?', o: ['Que en el fútbol ciertas violencias están legitimadas', 'Que el fútbol saca lo que la persona es en realidad', 'Que la multitud lo vuelve irracional por un rato', 'Que seguramente forma parte de una barra'], e: 'En la cancha ciertas conductas se ven como aceptables. No es su “verdadera naturaleza” ni pura irracionalidad: es una violencia aprendida y permitida en ese contexto.', t: 'violencia-en-el-futbol' },
  { p: 'Llamar “bestias” o “locos” a quienes cometen hechos violentos…', o: ['Oculta sus causas sociales y culturales', 'Ayuda a tomar conciencia de la gravedad', 'Permite identificar a quienes hay que excluir', 'Describe un rasgo de personalidad'], e: 'Esas palabras presentan la violencia como algo irracional o individual y tapan que se aprende y se reproduce culturalmente.', t: 'violencia-en-el-futbol' },
  { p: 'Dentro de la barra, no pelear se vive como…', o: ['Una deshonra, como “falta de hombría”', 'Una forma de cuidar al grupo', 'Una decisión respetada si se alienta', 'Un acuerdo tácito con la policía'], e: 'En la lógica del aguante, no pelear es perder hombría. Por eso el tema conecta la violencia en el fútbol con el modelo patriarcal.', t: 'violencia-en-el-futbol' },
  { p: 'Un dirigente recibe a la barra como “embajadora del club”. Según la guía, eso…', o: ['Habilita la violencia', 'Ayuda a controlarla desde adentro', 'Es una forma de prevención', 'Reduce el poder de la barra'], e: 'Darle reconocimiento institucional a la barra le da poder y habilita la violencia.', t: 'violencia-en-el-futbol' },
  { p: '¿Por qué la identidad del "aguante" es inestable?', o: ['Porque hay que demostrarla una y otra vez', 'Porque depende de los resultados del equipo', 'Porque cambia en cada temporada', 'Porque la otorgan los dirigentes'], e: 'No alcanza con decir que se tiene aguante: hay que demostrarlo una y otra vez.', t: 'violencia-en-el-futbol' },
  { p: 'Si la violencia se ve como parte de la “naturaleza” de algunas personas, ¿qué respuesta queda?', o: ['La represión', 'La prevención con todos los actores', 'El trabajo con los medios', 'Las normas de convivencia en los clubes'], e: 'Si se la cree natural, solo queda reprimir. Entenderla como aprendida abre la puerta a prevenir con todos los actores.', t: 'violencia-en-el-futbol' },

  // ── Diversidad sexual ──
  { p: 'Una persona trans es aquella cuya identidad de género…', o: ['Es distinta del sexo asignado al nacer', 'Coincide con el sexo asignado al nacer', 'No incluye ninguna atracción sexual', 'Depende de su orientación sexual'], e: 'Transgénero: la identidad es diferente al sexo asignado al nacer.', t: 'diversidad-sexual' },
  { p: 'Según la guía, ¿qué relación hay entre la identidad de género y el sexo asignado al nacer?', o: ['Pueden coincidir o no', 'La identidad se define por el sexo asignado', 'La identidad se define en la pubertad', 'Coinciden, salvo en personas intersex'], e: 'Pueden coincidir (personas cis) o no (personas trans). Ser intersex tiene que ver con las características del cuerpo, no con la identidad.', t: 'diversidad-sexual' },
  { p: '¿Qué es la asexualidad?', o: ['La falta de atracción sexual hacia otros', 'La atracción por más de un género', 'Una identidad que no es hombre ni mujer', 'La atracción por el mismo sexo'], e: 'Es una orientación: la falta de atracción sexual hacia otras personas.', t: 'diversidad-sexual' },
  { p: 'Según la guía, la discriminación por orientación sexual o identidad de género…', o: ['Vulnera múltiples derechos humanos', 'Afecta sobre todo a la vida en pareja', 'Se redujo a casos aislados desde la Ley 26.618', 'Se concentra en el ámbito laboral'], e: 'Vulnera muchos derechos a la vez. Las leyes ayudaron, pero los crímenes de odio de 2025 muestran que no se redujo a casos aislados.', t: 'diversidad-sexual' },
  { p: 'Según la ONU, frente a los derechos LGBTI+ el Estado debe…', o: ['Intervenir activamente para protegerlos', 'Garantizarlos cuando haya una denuncia', 'Apoyar a las ONG que los defienden', 'Reconocerlos sin políticas específicas'], e: 'El Estado tiene que intervenir activamente, no esperar denuncias ni delegar la protección.', t: 'diversidad-sexual' },
  { p: 'Según el Observatorio Nacional de Crímenes de Odio LGBT+, ¿quiénes fueron la mayoría de las víctimas en 2025?', o: ['Las travestis y mujeres trans', 'Los varones gays', 'Las mujeres lesbianas', 'Las personas bisexuales'], e: 'Las travestis y mujeres trans fueron el 63 % de las víctimas. En 2025 hubo 227 crímenes de odio, un 62 % más que en 2024.', t: 'diversidad-sexual' },

  // ── Entendimiento de la ira ──
  { p: 'Usar la ira para castigar o vengarse, a la larga…', o: ['Aleja o vuelve enemigos a quienes más queremos', 'Hace que los demás nos respeten más', 'Deja en claro quién tiene la razón', 'Resuelve el conflicto, aunque duela'], e: 'La venganza deja heridas y resentimiento: termina alejando a las personas cercanas en lugar de resolver el conflicto.', t: 'entendimiento-de-la-ira' },
  { p: 'Antes se creía que gritar o pegarle a una almohada era terapéutico. ¿Qué encontraron las investigaciones?', o: ['Que descargarlo así no ayuda y a veces lo aumenta', 'Que funciona si después se habla con calma del tema', 'Que sirve en niños y adolescentes, pero no en adultos', 'Que es útil si se practica todos los días un rato'], e: 'Descargar el enojo de esa forma puede mantenerlo o aumentarlo. Lo que ayuda es reconocerlo a tiempo y expresarlo de forma asertiva.', t: 'entendimiento-de-la-ira' },
  { p: 'Una persona empieza a pensar: “me está provocando a propósito”. ¿Qué tipo de señal de intensificación del enojo es?', o: ['Cognitiva', 'Fisiológica', 'Conductual', 'Emocional'], e: 'Las señales de intensificación pueden ser fisiológicas, conductuales, emocionales o cognitivas; un pensamiento que atribuye mala intención es una señal cognitiva.', t: 'entendimiento-de-la-ira' },
  { p: 'La explosión del ciclo de agresión equivale, en la escala del enojo, al…', o: ['10', '1', '5', '7'], e: 'Es la descarga descontrolada en forma de agresión física o verbal.', t: 'entendimiento-de-la-ira' },
  { p: 'Perder seres queridos, sentir culpa y arrepentimiento son parte de la fase de…', o: ['Post-explosión', 'Intensificación', 'Explosión', 'Luna de miel'], e: 'Son consecuencias de la post-explosión del ciclo de agresión. La luna de miel pertenece al ciclo de la violencia de Walker, que es otro modelo.', t: 'entendimiento-de-la-ira' },
  { p: 'Los pensamientos que desencadenan el enojo nos hacen sentir…', o: ['Víctimas de un daño hecho a propósito', 'Responsables de lo que ocurrió', 'Confundidos sobre lo que pasó', 'Tristes por algo que perdimos'], e: 'Los pensamientos desencadenantes interpretan que el otro nos dañó a propósito. Eso, sumado al dolor, enciende el enojo.', t: 'entendimiento-de-la-ira' },

  // ── El cerebro y las emociones ──
  { p: '¿Qué hace el sistema límbico con lo que nos produce dolor?', o: ['Nos lleva a evitarlo', 'Lo guarda para analizarlo después', 'Lo transforma en enojo', 'Lo bloquea hasta que pasa'], e: 'Nos lleva a evitar lo que duele y a buscar lo que da placer. Analizar es tarea de la neocorteza.', t: 'cerebro-y-emociones' },
  { p: 'Según la visión actual de las neurociencias, ¿qué importa más del cerebro?', o: ['Cómo se conectan sus partes', 'La función aislada de cada parte', 'El tamaño de cada estructura', 'La antigüedad de cada parte'], e: 'Importa cómo trabajan en conjunto; además, la evolución no fue escalonada.', t: 'cerebro-y-emociones' },
  { p: 'Al analizar una emoción, la pregunta “¿qué querías hacer?” sirve para…', o: ['Reconocer el impulso', 'Describir la situación', 'Ver las consecuencias', 'Encontrar al culpable'], e: 'No siempre se actúa: notar que se controló un impulso da esperanza de controlar otros.', t: 'cerebro-y-emociones' },
  { p: '¿Por qué las emociones secundarias causan más problemas que las primarias?', o: ['Porque encadenan una emoción negativa con otra', 'Porque son más intensas que las primarias', 'Porque aparecen sin ningún motivo', 'Porque duran menos que las primarias'], e: 'Encadenan emociones: enojo, después culpa por el enojo, después tristeza. No son necesariamente más intensas ni aparecen sin motivo.', t: 'cerebro-y-emociones' },
  { p: 'Marcela se desborda al encontrar, una vez más, a su marido alcoholizado. Si su emoción primaria es la ira, ¿cuáles son las secundarias, según la guía?', o: ['Desesperanza y vergüenza', 'Tensión muscular y náuseas', 'Entusiasmo y alegría', 'Sorpresa y curiosidad'], e: 'La guía identifica la ira como primaria y la desesperanza y la vergüenza como secundarias. La tensión muscular y las náuseas son sensaciones corporales, no emociones.', t: 'cerebro-y-emociones' },

  // ── Abordaje emocional (IFS) ──
  { p: 'En el modelo IFS, consumir o comprar en exceso después de un rechazo es una forma de…', o: ['Distraer del dolor, como un bombero', 'Prevenir el dolor, como un gerente', 'Expresar el dolor del exiliado', 'Cuidar a otros para sentirse querido'], e: 'Es una reacción de bombero: apaga el dolor cuando ya se activó. Los gerentes, en cambio, se anticipan para que no se active.', t: 'abordaje-emocional-ifs' },
  { p: 'En el modelo IFS, ¿qué intenta una parte cuando se activa?', o: ['Sacar al Yo del control y tomar su lugar', 'Unirse al Yo para sanar juntas', 'Sanar al exiliado por su cuenta', 'Avisarle al exiliado que hay peligro'], e: 'La parte activada desplaza al Yo y toma el control. Sanar a los exiliados lo hace el Yo, no las partes.', t: 'abordaje-emocional-ifs' },
  { p: 'En el modelo IFS, ¿cómo conviene tratar a una parte que nos afecta?', o: ['Escucharla desde el Yo, con curiosidad', 'Fundirse con ella para entenderla mejor', 'Convencerla con argumentos de que se calme', 'Ignorarla hasta que deje de activarse'], e: 'Se la escucha desde el Yo, con curiosidad. Fundirse con ella es justamente perder el Yo, y discutirla o ignorarla la refuerza.', t: 'abordaje-emocional-ifs' },
  { p: '¿Qué es “reparentalizar” al exiliado?', o: ['Darle desde el Yo lo que necesitó de niño', 'Pedirles perdón a los propios padres', 'Revivir la infancia para cambiarla', 'Buscar a alguien que nos cuide como un padre'], e: 'Es darle desde el propio Yo el cuidado que esa parte necesitó y no recibió. No depende de los padres reales ni de otra persona.', t: 'abordaje-emocional-ifs' },
  { p: 'Según el modelo IFS, ¿qué determina cómo nos sentimos?', o: ['Los residuos emocionales de lo vivido', 'Las experiencias tal como ocurrieron', 'Lo que pasa en el presente', 'La opinión que tienen los demás'], e: 'No son las experiencias en sí, sino los residuos emocionales que dejaron y que cargan las partes.', t: 'abordaje-emocional-ifs' },
  { p: '¿Cómo se siente el cuerpo cuando está presente el Yo?', o: ['En paz, abierto y con energía', 'Tranquilo, pero sin energía', 'Alerta y listo para actuar', 'Liviano y desconectado'], e: 'Con el Yo presente hay calma y energía a la vez. La alerta es propia de los protectores, y la desconexión puede ser una defensa.', t: 'abordaje-emocional-ifs' },

  // ── Pensamientos automáticos ──
  { p: '¿Por qué se dice que los pensamientos automáticos son “taquigráficos”?', o: ['Son pocas palabras o una imagen breve', 'Se anotan rápido en el diario', 'Usan un lenguaje técnico', 'Son frases largas, pero confusas'], e: 'Como la taquigrafía, son muy breves: una palabra, una frase corta o una imagen.', t: 'pensamientos-automaticos' },
  { p: '¿Por qué los pensamientos automáticos casi nunca se cuestionan?', o: ['Porque casi no se notan', 'Porque suelen ser ciertos', 'Porque los aprendimos de otros', 'Porque los comparte mucha gente'], e: 'Pasan tan rápido que casi no se notan, y por eso se creen sin revisarlos. Que sean aprendidos no explica que no se cuestionen.', t: 'pensamientos-automaticos' },
  { p: 'Según la guía, ¿qué característica de los pensamientos automáticos es la mayor fuente de ansiedad?', o: ['Que tienden a dramatizar', 'Que son taquigráficos', 'Que son idiosincráticos', 'Que son aprendidos'], e: 'Tienden a dramatizar: predicen catástrofes y suponen lo peor. Por eso son la mayor fuente de ansiedad.', t: 'pensamientos-automaticos' },
  { p: 'Para reconocer un pensamiento automático, conviene…', o: ['Reconstruir la escena en cámara lenta', 'Preguntarse quién tuvo la culpa', 'Esperar a que se calme la emoción y olvidarlo', 'Pensar en otra cosa hasta calmarse'], e: 'Reconstruir la escena paso a paso permite encontrar el pensamiento que disparó la emoción.', t: 'pensamientos-automaticos' },
  { p: 'La frase taquigráfica “loco”, desarrollada, puede significar…', o: ['“Siento que pierdo el control”', '“Él me está dominando”', '“Ella está aburrida”', '“Voy a estar acá toda la noche”'], e: 'Desarrollarla lleva a la idea completa: “siento que pierdo el control y eso podría significar…”.', t: 'pensamientos-automaticos' },
  { p: 'Que cada persona reaccione distinto ante la misma situación muestra que los pensamientos automáticos son…', o: ['Idiosincráticos', 'Taquigráficos', 'Racionales', 'Hereditarios'], e: 'Idiosincráticos: propios de cada persona. También son taquigráficos, pero eso describe su forma breve, no las diferencias entre personas.', t: 'pensamientos-automaticos' },

  // ── Distorsiones cognitivas ──
  { p: '"Debería haber llegado hace una hora; seguro está con otra persona". ¿Qué distorsión es?', o: ['Conclusión arbitraria', 'Generalización excesiva', 'Pensamiento dicotómico', 'Filtraje'], e: 'Saca una conclusión sin pruebas suficientes.', t: 'distorsiones-cognitivas' },
  { p: '"No la golpeé, solo la agarré fuerte". ¿Qué distorsión aparece?', o: ['Minimización', 'Maximización', 'Personalización', 'Abstracción selectiva'], e: 'Achica la importancia del hecho y niega el impacto real y la responsabilidad de una conducta violenta.', t: 'distorsiones-cognitivas' },
  { p: 'El jefe frunció el ceño una vez en una reunión que salió bien, y alguien concluye "salió todo mal". ¿Qué distorsión es?', o: ['Abstracción selectiva', 'Falacia de recompensa divina', 'Minimización', 'Personalización'], e: 'Se fija en un detalle fuera de contexto y juzga toda la situación por él.', t: 'distorsiones-cognitivas' },
  { p: 'Alguien se sacrificó años por su familia y está amargado porque “nadie se lo reconoció”. ¿Qué distorsión puede haber?', o: ['Falacia de recompensa divina', 'Personalización', 'Abstracción selectiva', 'Pensamiento dicotómico'], e: 'La falacia de recompensa divina espera que el sacrificio y la abnegación sean premiados algún día. Cuando no llega, aparecen la amargura y el resentimiento.', t: 'distorsiones-cognitivas' },
  { p: '¿Qué distingue al filtraje dentro de la abstracción selectiva?', o: ['Que solo retiene lo negativo', 'Que supone lo que piensan los demás', 'Que generaliza a partir de un hecho', 'Que ve todo en extremos opuestos'], e: 'El filtraje es una forma de abstracción selectiva que se queda solo con lo negativo y descarta lo positivo.', t: 'distorsiones-cognitivas' },
  { p: '¿Qué se anota en el registro para trabajar las distorsiones?', o: ['Contexto, situación, emoción, pensamiento y distorsión', 'Acontecimiento, creencia, consecuencia y debate', 'Situación, señales del enojo y nivel en la escala', 'Pensamiento, prueba a favor y prueba en contra'], e: 'El registro de distorsiones anota contexto, situación, emoción, pensamiento y distorsión. A, B, C y D es el esquema de Ellis.', t: 'distorsiones-cognitivas' },

  // ── Pensar correctamente ──
  { p: 'En el ABC de Ellis, ¿dónde se encuentra la solución al problema?', o: ['En la D', 'En la A', 'En la C', 'En la B'], e: 'A activa, B (la creencia) causa C, y en D está la solución: debatir la creencia irracional.', t: 'pensar-correctamente' },
  { p: 'Frente al mito “hay gente malvada que debe ser castigada”, ¿qué señala la guía para los conflictos cotidianos?', o: ['Una mala conducta no hace mala a toda la persona', 'La gente que daña suele hacerlo a propósito', 'El castigo es la forma más eficaz de corregir', 'Hay que perdonar todo para estar en paz'], e: 'Se puede rechazar una conducta sin condenar a la persona entera. Eso no quiere decir tolerar la violencia, que sigue teniendo límites.', t: 'pensar-correctamente' },
  { p: 'Según Ellis, preocuparse sin parar por algo peligroso…', o: ['No impide que ocurra', 'Lo vuelve menos probable', 'Ayuda a sentir control', 'Prepara para enfrentarlo'], e: 'La preocupación constante no evita el peligro y nos desgasta. Prepararse es hacer algo útil, no preocuparse sin parar.', t: 'pensar-correctamente' },
  { p: 'Evitar las dificultades en lugar de enfrentarlas…', o: ['Crea más problemas a la larga', 'Da alivio y permite descansar', 'Ayuda a esperar el mejor momento', 'Protege la autoestima'], e: 'Evitar alivia en el momento, pero los problemas crecen y la confianza baja.', t: 'pensar-correctamente' },
  { p: 'Frente a la idea de que cada problema tiene una solución perfecta, la guía sugiere…', o: ['Elegir una buena y, si falla, probar otra', 'Esperar hasta encontrar la perfecta', 'Pedir que otro decida por nosotros', 'Probar todas las opciones a la vez'], e: 'No existe la solución perfecta: se elige una razonable y se ajusta sobre la marcha.', t: 'pensar-correctamente' },
  { p: 'En los vínculos cotidianos, ante el mito de que hay que cambiar a los demás, ¿qué propone la guía?', o: ['Vivir y dejar vivir', 'Insistir hasta que cambien', 'Cambiar uno primero para que el otro cambie', 'Alejarse de quien no cambia'], e: 'No podemos cambiar a los demás. Esto vale para los desacuerdos cotidianos: ante la violencia, lo que corresponde es protegerse y pedir ayuda.', t: 'pensar-correctamente' },

  // ── Teoría del apego ──
  { p: 'Un bebé llora y quien lo cuida a veces lo consuela con cariño y otras lo ignora. ¿Qué estilo se asocia?', o: ['Ambivalente', 'Seguro', 'Evitativo', 'Desorganizado'], e: 'En el apego ambivalente, quien cuida responde de forma inconstante; predominan la inseguridad y la demanda permanente de afecto.', t: 'teoria-del-apego' },
  { p: '¿Qué mostraron los experimentos de Harlow con monos?', o: ['La necesidad de contacto, más allá del alimento', 'Que las crías siguen a lo primero que ven moverse', 'Que el apego depende de quién alimenta a la cría', 'Que las crías aisladas se adaptan sin problemas'], e: 'Las crías preferían una “madre” de tela suave antes que una de alambre con comida. Seguir a lo primero que se mueve es lo que mostró Lorenz.', t: 'teoria-del-apego' },
  { p: 'Konrad Lorenz mostró que las crías de ave…', o: ['Se vinculan con la primera figura en movimiento', 'Necesitan más el contacto que el alimento', 'Imitan el canto de sus padres desde el nido', 'Reconocen a su madre por el olor de las plumas'], e: 'Es la impronta: un vínculo fuerte con la primera figura en movimiento que ven.', t: 'teoria-del-apego' },
  { p: '¿Qué estilo es frecuente cuando la figura que debería dar seguridad también da miedo?', o: ['Desorganizado', 'Seguro', 'Ambivalente', 'Evitativo'], e: 'El estilo desorganizado, que sumaron Main y Solomon (1990). Es frecuente en situaciones de maltrato, aunque no solo en ellas.', t: 'teoria-del-apego' },
  { p: '¿Qué puede dar seguridad a un adulto con una historia de apego inseguro?', o: ['Vínculos posteriores: amistades, pareja o terapia', 'Nada: el apego queda fijo desde la infancia', 'Tomar distancia de los vínculos más cercanos', 'Volver a vivir cerca de su familia de origen'], e: 'Los vínculos posteriores pueden dar una seguridad ganada. El apego no queda fijo.', t: 'teoria-del-apego' },
  { p: 'En la teoría del apego, "accesibilidad" se refiere a…', o: ['Cuánto se espera que quien cuida esté disponible', 'La facilidad para llegar a un servicio de salud', 'La capacidad del niño de explorar el mundo', 'La cantidad de contacto físico con el bebé'], e: 'Es la expectativa sobre la disponibilidad y la respuesta de quien cuida; esa expectativa va formando el carácter.', t: 'teoria-del-apego' },

  // ── Personalidad ──
  { p: '¿Qué afecto suele llevar a consulta a una persona con estilo paranoide?', o: ['La ansiedad constante', 'La tristeza por la soledad', 'El enojo con quienes la rodean', 'La culpa por sus sospechas'], e: 'La vigilancia permanente produce ansiedad, que es lo que suele llevar a consultar.', t: 'personalidad' },
  { p: '¿Cómo ve a los demás la personalidad obsesivo-compulsiva?', o: ['Irresponsables o incompetentes', 'Críticos y despectivos', 'Fuertes y protectores', 'Traicioneros y manipuladores'], e: 'Ve a los demás como irresponsables. Fuertes y protectores es la mirada del estilo dependiente; traicioneros y manipuladores, la del paranoide.', t: 'personalidad' },
  { p: '¿Qué amenaza más a la personalidad narcisista?', o: ['Lo que dañe su autoestima', 'El acercamiento excesivo', 'El rechazo o el abandono', 'Los errores y el desorden'], e: 'Su clave es la autoexaltación. Las otras amenazas son de otros estilos.', t: 'personalidad' },
  { p: 'La personalidad por evitación querría estar cerca de los demás, pero teme…', o: ['Ser herida, rechazada o fracasar', 'Que los demás se le acerquen demasiado', 'Que la manipulen o la desvaloricen', 'Quedarse sola y sin protección'], e: 'Teme el rechazo y el fracaso. Que se le acerquen demasiado es la amenaza del estilo esquizoide; que la manipulen, la del paranoide; quedarse sola, la del dependiente.', t: 'personalidad' },
  { p: '¿Qué siente la personalidad por dependencia cuando su vínculo está asegurado?', o: ['Euforia', 'Cólera', 'Indiferencia', 'Culpa'], e: 'Ansiedad ante una posible ruptura, depresión si pierde a la figura, euforia si está asegurada.', t: 'personalidad' },
  { p: '¿Cuál es el conflicto central del estilo pasivo-agresivo?', o: ['Querer aprobación y a la vez autonomía', 'Querer admiración sin dar nada a cambio', 'Querer estar solo y acompañado', 'Querer orden en medio del caos'], e: 'Desea las ventajas de la autoridad y a la vez conservar su autonomía.', t: 'personalidad' },

  // ── El duelo ──
  { p: 'Pocos días después de la muerte de su pareja, una mujer sigue su rutina casi en automático, con estallidos de angustia. ¿En qué fase está?', o: ['Embotamiento', 'Anhelo y búsqueda', 'Desorganización y desesperanza', 'Reorganización'], e: 'En el embotamiento la persona puede seguir casi en automático, tensa, con estallidos de angustia o de enojo.', t: 'duelo' },
  { p: 'Meses después de la pérdida, alguien siente la presencia de su padre y cree oír su voz al entrar en casa. ¿Qué fase se asocia?', o: ['Anhelo y búsqueda', 'Embotamiento', 'Reorganización', 'Ausencia de duelo'], e: 'En el anhelo y la búsqueda aparecen sentir la presencia de la persona o interpretar señales de que volvió.', t: 'duelo' },
  { p: '¿Qué tienen en común el duelo crónico y la ausencia de duelo?', o: ['La pérdida no se acepta como definitiva', 'En los dos, las emociones son muy intensas', 'En los dos, la persona no siente nada', 'Los dos se resuelven solos con el tiempo'], e: 'En los dos casos no se acepta la pérdida. En uno el dolor no termina; en el otro, no aparece.', t: 'duelo' },
  { p: '¿Cuál de estas señales, si no cede con el paso del tiempo, puede indicar un duelo complicado?', o: ['Una tristeza profunda que no cede', 'Llorar al recordar a la persona', 'Sentir enojo en las primeras semanas', 'Sentir a veces su presencia'], e: 'La tristeza, el enojo y hasta sentir la presencia de quien murió son parte de un duelo esperable. Lo que preocupa es que la tristeza no ceda con el tiempo. Si aparecen ideas de quitarse la vida, hay que pedir ayuda enseguida (línea 135).', t: 'duelo' },
  { p: '¿Qué ayuda a prevenir que el duelo se complique?', o: ['Contar lo que pasó a todos, también a los chicos', 'Ocultarles la muerte a los más chicos de la casa', 'Evitar hablar de la persona que falleció', 'Retomar la rutina de siempre lo antes posible'], e: 'Hablar con claridad, también con los chicos, ayuda. Retomar la rutina puede servir, pero apurarlo para no sentir no previene complicaciones.', t: 'duelo' },
  { p: '¿Qué función cumple un velatorio para quienes quedan?', o: ['Ayuda a sentir que la pérdida es real', 'Permite postergar el dolor para después', 'Es sobre todo un deber hacia quien murió', 'Reemplaza la necesidad de hablar del tema'], e: 'Despedirse ayuda a que la pérdida se vuelva real, el primer paso del duelo.', t: 'duelo' },

  // ── Habilidades interpersonales ──
  { p: '¿Qué pasa a corto plazo con la conducta pasiva?', o: ['Parece proteger la relación', 'Destruye la relación enseguida', 'Resuelve el conflicto de fondo', 'Hace que el otro cambie'], e: 'A la larga genera frustración y resentimiento y vuelve insostenible la relación.', t: 'habilidades-interpersonales' },
  { p: 'El equilibrio “yo quiero – los otros quieren” implica…', o: ['Decir lo propio y averiguar lo ajeno', 'Ceder para no dañar la relación', 'Cumplir con lo que uno debería hacer', 'Lograr que el otro acepte lo nuestro'], e: 'Saber y decir lo que se desea, averiguar lo que desea el otro, negociar y dar lo que se pueda. Ceder es la conducta pasiva; el “debería” es el otro equilibrio.', t: 'habilidades-interpersonales' },
  { p: 'Cargarse de “debería” en una relación…', o: ['Hace que uno quiera escaparse de ella', 'Genera resentimiento en la otra persona', 'Demuestra compromiso y responsabilidad', 'Le da estabilidad y previsibilidad'], e: 'Es el equilibrio “quiero – debería”: cargarse de “debería” convierte la relación en una carga de la que se quiere escapar. El resentimiento del otro aparece al revés, cuando uno se centra solo en lo que quiere.', t: 'habilidades-interpersonales' },
  { p: 'Según la guía, jugar con objetos mientras se habla puede indicar…', o: ['Nerviosismo', 'Seguridad', 'Interés', 'Alegría'], e: 'Es un ejemplo de lenguaje corporal; un apretón de manos, en cambio, transmite seguridad. Es una señal posible, no una regla: ante la duda, conviene preguntar.', t: 'habilidades-interpersonales' },
  { p: 'En el esquema para resolver problemas, ¿qué se pregunta al evaluar las opciones?', o: ['¿Qué gano y qué pierdo?', '¿Quién tiene la culpa?', '¿Qué dirán los demás?', '¿Cuánto tiempo tengo?'], e: 'Se analizan ventajas, desventajas y consecuencias de cada opción.', t: 'habilidades-interpersonales' },
  { p: 'Si los resultados de la solución elegida son negativos, ¿qué conviene hacer?', o: ['Revisar el error o buscar otra solución', 'Abandonar el problema para siempre', 'Culpar a las personas que participaron en él', 'Repetir lo mismo con más fuerza'], e: 'Es el último paso del esquema: analizar los resultados.', t: 'habilidades-interpersonales' },

  // ── Límites y negociación ──
  { p: 'Decir “no puedo porque soy torpe” al poner un límite…', o: ['Deja espacio para que nos convenzan', 'Es la forma más firme y clara de negarse', 'Muestra seguridad y confianza', 'Evita cualquier discusión'], e: 'Mejor “no lo haré” o “no quiero hacerlo”, que dejan menos lugar para discutir.', t: 'limites-y-negociacion' },
  { p: '“Puedo revisar tu proyecto, pero no voy a participar en la producción” es un ejemplo de…', o: ['Ser específico', 'Pedir disculpas', 'Retrasar la respuesta', 'Descalificarse'], e: 'Aclarar qué se está dispuesto a hacer y qué no.', t: 'limites-y-negociacion' },
  { p: '“Quiero que laves los platos antes de mirar televisión” expresa un deseo en términos…', o: ['Conductuales', 'Vagos', 'Emocionales', 'Agresivos'], e: 'Es el segundo paso de la negociación: decir claramente qué se espera que el otro haga.', t: 'limites-y-negociacion' },
  { p: 'Si al otro no le gusta nuestra propuesta, ¿cuál es el paso siguiente?', o: ['Pedir una contrapropuesta', 'Insistir con la misma', 'Abandonar la negociación', 'Ceder en todo'], e: 'Animar al otro a plantear una alternativa que satisfaga a ambas partes.', t: 'limites-y-negociacion' },
  { p: '¿Qué se usa para escuchar el punto de vista del otro en una negociación?', o: ['Preguntas abiertas y paráfrasis', 'Interrupciones y correcciones', 'Silencios y gestos de rechazo', 'Argumentos para refutarlo'], e: 'Escucha activa: preguntas abiertas, aclaraciones y paráfrasis.', t: 'limites-y-negociacion' },
  { p: 'Antes de decir que no, la primera pauta es…', o: ['Reconocer las necesidades del otro', 'Pedir disculpas por tener que negarse', 'Buscar una excusa creíble', 'Cambiar rápido de tema'], e: 'Pedir más información y, si hace falta, reformular el pedido para comprobar que se entendió.', t: 'limites-y-negociacion' },

  // ── Nuevas familias ──
  { p: 'Una madre que cría sola a su hija desde el nacimiento forma una familia…', o: ['Monoparental', 'Extensa', 'Ensamblada', 'Nuclear'], e: 'Es una familia monoparental; cuando la madre cría sola desde el inicio, a veces se la llama monomarental.', t: 'nuevas-familias' },
  { p: 'Después de separarse, un padre le dice a su hijo: "No le hagas caso a tu madre". ¿Qué está haciendo?', o: ['Desautorizar al otro progenitor', 'Ejercer la responsabilidad parental', 'Proteger a su hijo de un riesgo', 'Enseñarle normas de convivencia'], e: 'Desautorizar al otro progenitor confunde a los hijos sobre a quién respetar.', t: 'nuevas-familias' },
  { p: '"No le cuentes esto a papá". Según la guía, pedir secretos así…', o: ['Pone a los hijos en un lugar que no les toca', 'Fortalece la confianza entre madre e hijo', 'Evita conflictos innecesarios en la familia', 'Es una parte normal de toda separación'], e: 'Pedirles que guarden secretos los pone en un lugar que no les corresponde.', t: 'nuevas-familias' },
  { p: 'Una madre pide medidas para proteger a sus hijos de un padre que ejerce violencia. Según la guía…', o: ['Es protegerlos, no "poner en contra"', 'Es desautorizar al otro progenitor', 'Es usarlos como moneda de cambio', 'Es obligarlos a elegir un bando'], e: 'Las pautas sobre la separación son para separaciones sin violencia. Cuando hay violencia, proteger a los hijos no es "desautorizar" ni "poner en contra", y las medidas de restricción de acercamiento pueden extenderse a ellos.', t: 'nuevas-familias' },
  { p: 'Según Grosman y Mesterman, la familia a veces puede ser…', o: ['Una escuela de violencia', 'Un espacio sin conflictos', 'Un refugio siempre seguro', 'Una institución sin cambios'], e: 'A veces es una escuela de violencia, donde niñas y niños aprenden que agredir sirve para controlar a los demás.', t: 'nuevas-familias' },
  { p: 'Cuando la tensión por trabajo o dinero se descarga como violencia sobre mujeres o hijos, ¿qué hay detrás, según la guía?', o: ['Una relación desigual de poder', 'Un estrés imposible de controlar', 'Una descarga normal de la tensión', 'Un problema de adicciones'], e: 'Pueden tensar la vida familiar, pero no explican ni justifican la violencia: cuando se descarga sobre mujeres o hijos, hay una relación desigual de poder.', t: 'nuevas-familias' },

  // ── Relajación avanzada ──
  { p: 'En la respiración con escenas de estrés, ¿qué intensidad de ira deben provocar las escenas?', o: ['Entre 5 y 7', 'Entre 3 y 5', 'Entre 7 y 9', 'Entre 1 y 3'], e: 'Se eligen dos escenas de ira moderada, entre 5 y 7 en una escala de 1 a 10.', t: 'relajacion-avanzada' },
  { p: 'En la respiración con escenas de estrés, ¿en cuántas partes se divide cada escena?', o: ['Tres', 'Dos', 'Cinco', 'Diez'], e: 'Tres partes, con un recordatorio de respirar al final de cada una. Dos es la cantidad de escenas, no de partes.', t: 'relajacion-avanzada' },
  { p: '¿Qué cambia en la relajación sin tensión respecto de la progresiva?', o: ['Se quita el paso de tensar', 'Se tensa el doble de tiempo', 'Se hace sin respirar hondo', 'Se hace mientras se camina'], e: 'Hasta ahí se relajaba aumentando la tensión; ahora se elimina ese paso.', t: 'relajacion-avanzada' },
  { p: 'En momentos de estrés, la palabra clave reemplaza a…', o: ['La respiración profunda', 'La tensión de cada músculo', 'La visualización de las escenas', 'La medición del nivel de estrés'], e: 'Se vuelve a las escenas de estrés y se reemplaza la respiración profunda por la palabra clave; las escenas se siguen visualizando.', t: 'relajacion-avanzada' },
  { p: 'Ante una situación estresante real, primero se repasa la escena sin relajarse para…', o: ['Ver dónde se acumula la tensión', 'Ensayar una respuesta para la próxima vez', 'Olvidar lo que pasó', 'Medir cuánto dura'], e: 'Después se concentra la relajación en esos grupos musculares.', t: 'relajacion-avanzada' },
];
